<script setup>
import { computed, onMounted, ref } from 'vue'
import { ArrowRight, BadgeCheck, CircleAlert, CloudOff, Database, FileDiff, RefreshCw, ShieldCheck, UserMinus, UsersRound } from '@lucide/vue'
import { applyLocalHrBatch, createLocalHrMapping, createLocalHrPreview, getLocalHrWorkspace } from '../api/localHr'

const workspace = ref({ organizations: [], selected: null, truthfulness: null })
const loading = ref(true), action = ref(''), error = ref(''), notice = ref('')
const selected = computed(() => workspace.value.selected)
const mapping = computed(() => selected.value?.mappings?.[0] || null)
const latestPreview = computed(() => selected.value?.batches?.find((item) => item.status === 'previewed') || null)

function detailText(value) { return typeof value === 'string' ? value : value?.message || value?.code || '操作失败' }
async function load() { loading.value = true; error.value = ''; try { workspace.value = await getLocalHrWorkspace() } catch (e) { error.value = detailText(e.detail || e.message) } finally { loading.value = false } }
async function run(key, command, message) { action.value = key; error.value = ''; notice.value = ''; try { await command(); notice.value = message; await load() } catch (e) { error.value = detailText(e.detail || e.message) } finally { action.value = '' } }
async function setup() { await run('mapping', () => createLocalHrMapping({ organization_id: selected.value.organization.id }), '字段映射 v1 已冻结') }
async function preview(kind) {
  const sample = selected.value.frozen_samples[kind]
  await run(`preview:${kind}`, () => createLocalHrPreview({ organization_id: selected.value.organization.id, mapping_version_id: mapping.value.id, ...sample }), `快照 ${sample.source_sequence} 预览已冻结，尚未写入员工主数据`)
}
async function apply(batch) { await run(`apply:${batch.id}`, () => applyLocalHrBatch(batch.id, { organization_id: selected.value.organization.id, expected_lock_version: batch.lock_version }), '预览批次已应用，员工投影与审计已更新') }
function actionLabel(value) { return ({ create: '新建', update: '更新', offboard: '离职', noop: '无变化', skip_leave: '跳过未知离职', conflict: '冲突', out_of_order: '乱序' })[value] || value }
onMounted(load)
</script>

<template>
  <div class="hr-page">
    <header class="page-header"><div><p class="eyebrow"><Database :size="14" /> FC4 inbound integration</p><h1>合成 HR 主数据同步</h1><p>以冻结员工快照演示字段映射、写前预览、幂等应用、离职撤销、冲突和乱序保护。</p></div><button class="icon-button" aria-label="刷新 HR 同步工作台" title="刷新" @click="load"><RefreshCw :size="17" /></button></header>
    <div v-if="error" class="message error"><CircleAlert :size="16" />{{ error }}</div><div v-if="notice" class="message success"><BadgeCheck :size="16" />{{ notice }}</div><div v-if="loading" class="message loading"><RefreshCw :size="16" class="spin" />正在恢复同步状态</div>
    <section v-if="!loading && workspace.truthfulness" class="boundary"><CloudOff :size="18" /><div><strong>{{ workspace.truthfulness.data_label }}</strong><span>{{ workspace.truthfulness.disclaimer }}</span></div></section>
    <section v-if="!loading && !selected" class="empty"><UsersRound :size="36" /><h2>尚无可管理的演示组织</h2><RouterLink class="primary" to="/enterprise-training">前往企业培训</RouterLink></section>
    <template v-else-if="!loading">
      <section class="facts"><div><span>组织</span><strong>{{ selected.organization.name }}</strong></div><div><span>真实员工数据</span><strong>不包含</strong></div><div><span>真实 HR 连接</span><strong>未连接</strong></div><div><span>应用方式</span><strong>预览后确认</strong></div></section>
      <section v-if="!mapping" class="setup"><FileDiff :size="30" /><div><h2>建立字段映射契约</h2><p>冻结 7 个源字段到规范员工字段的一对一映射，后续快照必须引用具体版本。</p></div><button class="primary" :disabled="action === 'mapping'" @click="setup">创建字段映射</button></section>
      <template v-else>
        <section class="mapping-band"><div><span>源系统</span><strong>{{ mapping.source_key }}</strong></div><div><span>映射版本</span><strong>v{{ mapping.version_number }}</strong></div><div><span>映射哈希</span><code>{{ mapping.mapping_hash.slice(0, 20) }}...</code></div></section>
        <div class="grid">
          <section class="panel"><div class="heading"><div><h2>1. 选择冻结快照</h2><p>预览只生成差异和阻断项，不修改组织、用户或岗位。</p></div></div><div class="snapshot-list"><article><div><span>序列 1</span><strong>初始员工快照</strong><small>2 名在职 · 1 名未知离职</small></div><button class="secondary" :disabled="Boolean(action)" @click="preview('initial')">预览初始批次</button></article><article><div><span>序列 2</span><strong>变更与离职快照</strong><small>1 名离职 · 1 名部门变更</small></div><button class="secondary" :disabled="Boolean(action)" @click="preview('change')">预览变更批次</button></article></div></section>
          <section class="panel"><div class="heading"><div><h2>2. 写前差异</h2><p>阻断冲突必须先修复；应用动作只能引用冻结预览。</p></div><span v-if="latestPreview">序列 {{ latestPreview.source_sequence }}</span></div><div v-if="!latestPreview" class="inline-empty">选择一个源快照生成写前预览。</div><template v-else><div class="counts"><div v-for="(count, key) in latestPreview.preview.counts" :key="key"><span>{{ actionLabel(key) }}</span><strong>{{ count }}</strong></div></div><div class="decision-list"><div v-for="item in latestPreview.preview.records" :key="item.external_employee_id"><strong>{{ item.external_employee_id }}</strong><span :class="item.action">{{ actionLabel(item.action) }}</span><small>{{ item.record.display_name }} · {{ item.record.department }}</small></div></div><button class="primary wide" :disabled="latestPreview.preview.blocking_conflicts > 0 || action === `apply:${latestPreview.id}`" @click="apply(latestPreview)"><ArrowRight :size="15" />确认应用该预览</button></template></section>
        </div>
        <section class="employees"><div class="heading"><div><h2>3. 员工主数据投影</h2><p>离职移除组织访问并撤销外部身份，但账号和历史学习证据保留。</p></div><span>{{ selected.employees.length }} 名员工</span></div><div v-if="!selected.employees.length" class="inline-empty">首个批次应用后显示员工投影。</div><div v-else class="employee-table"><div class="thead"><span>员工</span><span>部门 / 岗位</span><span>源序列</span><span>状态</span></div><div v-for="employee in selected.employees" :key="employee.external_employee_id" class="trow"><div><strong>{{ employee.display_name }}</strong><code>{{ employee.external_employee_id }}</code></div><div><strong>{{ employee.department }}</strong><small>{{ employee.job_title }}</small></div><span>{{ employee.source_sequence }}</span><span class="state" :class="employee.employment_status"><UserMinus v-if="employee.employment_status === 'leave'" :size="13" /><ShieldCheck v-else :size="13" />{{ employee.employment_status === 'leave' ? '已离职 · 访问移除' : '在职 · 可访问' }}</span></div></div></section>
        <section class="history"><div class="heading"><div><h2>同步批次</h2><p>重复快照复用同一批次，历史预览与结果持续可审计。</p></div></div><div v-for="batch in selected.batches" :key="batch.id" class="batch"><span>序列 {{ batch.source_sequence }}</span><strong>{{ batch.source_snapshot_id }}</strong><code>{{ batch.source_hash.slice(0, 16) }}...</code><span class="state" :class="batch.status">{{ batch.status === 'applied' ? '已应用' : '待确认' }}</span></div></section>
      </template>
    </template>
  </div>
</template>

<style scoped>
.hr-page{max-width:1320px;margin:0 auto;padding:4px 2px 42px;color:#20272a}.page-header{display:flex;justify-content:space-between;align-items:flex-start;padding:24px 2px 20px;border-bottom:1px solid #dce2e5}.page-header h1{font-size:24px;font-weight:750;margin:6px 0}.page-header>div>p:last-child{font-size:13px;color:#667177}.eyebrow{display:flex;align-items:center;gap:7px;color:#1f6370;font-size:11px;font-weight:700;text-transform:uppercase}.icon-button{width:36px;height:36px;display:grid;place-items:center;border:1px solid #d8dfe2;background:#fff;border-radius:7px}.message{display:flex;align-items:center;gap:8px;padding:11px 14px;margin-top:12px;font-size:11px}.message.error{background:#fff1ef;color:#963f35}.message.success{background:#eef8f1;color:#276046}.message.loading{background:#f4f7f8;color:#56646a}.boundary{display:flex;align-items:center;gap:10px;padding:12px 15px;background:#fff8e6;border-bottom:1px solid #e4d7ad;color:#65511f}.boundary div{display:flex;flex-wrap:wrap;gap:5px 14px}.boundary strong{font-size:11px}.boundary span{font-size:10px;color:#78693f}.facts{display:grid;grid-template-columns:repeat(4,1fr);background:#f6f9fa;border-bottom:1px solid #dce2e5}.facts div{padding:14px 18px;border-right:1px solid #e0e6e8}.facts span,.mapping-band span{display:block;font-size:9px;color:#77858a}.facts strong,.mapping-band strong{font-size:12px}.setup{min-height:310px;display:flex;justify-content:center;align-items:center;gap:18px}.setup h2{font-size:16px}.setup p{font-size:10px;color:#758187;margin-top:4px}.mapping-band{display:grid;grid-template-columns:1fr 1fr 1.4fr;padding:16px 18px;border-bottom:1px solid #dce2e5}.mapping-band code{font-size:9px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:28px;border-bottom:1px solid #dce2e5}.panel{padding:25px 0}.panel:first-child{padding-right:28px;border-right:1px solid #dce2e5}.heading{display:flex;align-items:flex-end;justify-content:space-between;gap:10px;margin-bottom:15px}.heading h2{font-size:15px}.heading p{font-size:10px;color:#748087;margin-top:4px}.heading>span{font-size:9px;padding:5px 8px;border:1px solid #c8d8dc;border-radius:5px;color:#47717a}.snapshot-list{border:1px solid #dce2e5}.snapshot-list article{display:grid;grid-template-columns:1fr auto;align-items:center;gap:12px;padding:14px;border-bottom:1px solid #e3e8ea}.snapshot-list article:last-child{border:0}.snapshot-list div,.employee-table .trow>div{display:flex;flex-direction:column}.snapshot-list span{font-size:8px;color:#748087}.snapshot-list strong{font-size:11px}.snapshot-list small{font-size:9px;color:#748087}.counts{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:#dde5e7}.counts div{background:#f5f8f9;padding:9px}.counts span{display:block;font-size:8px;color:#758187}.counts strong{font-size:14px}.decision-list{border:1px solid #dce2e5;margin:10px 0}.decision-list>div{display:grid;grid-template-columns:1fr auto;gap:3px 10px;padding:9px 11px;border-bottom:1px solid #e5eaec}.decision-list>div:last-child{border:0}.decision-list strong{font-size:10px}.decision-list span{font-size:9px}.decision-list small{grid-column:1/-1;font-size:8px;color:#78848a}.decision-list .offboard,.decision-list .conflict{color:#99483d}.employees,.history{padding:25px 0;border-bottom:1px solid #dce2e5}.employee-table{border:1px solid #dce2e5}.thead,.trow{display:grid;grid-template-columns:1fr 1.4fr .4fr .8fr;align-items:center;gap:12px;padding:10px 14px}.thead{background:#f4f7f8;font-size:9px;color:#748087}.trow{border-top:1px solid #e3e8ea}.trow strong{font-size:10px}.trow code,.trow small{font-size:8px;color:#78848a}.state{display:inline-flex;align-items:center;gap:5px;width:max-content;padding:4px 7px;border-radius:4px;font-size:9px}.state.active,.state.applied{background:#edf7f0;color:#246246}.state.leave{background:#fff0ed;color:#93463d}.state.previewed{background:#fff6df;color:#76571e}.batch{display:grid;grid-template-columns:auto 1fr 1fr auto;align-items:center;gap:14px;padding:11px 0;border-bottom:1px solid #e3e8ea}.batch>span:first-child{font-size:9px;color:#65737a}.batch strong{font-size:10px}.batch code{font-size:8px;color:#77858a}.primary,.secondary{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:0;border-radius:6px;padding:8px 11px;font-size:10px;font-weight:650;cursor:pointer;text-decoration:none}.primary{background:#245f69;color:#fff}.secondary{background:#eaf2f4;color:#285d67}.wide{width:100%}.primary:disabled,.secondary:disabled{opacity:.5;cursor:not-allowed}.inline-empty,.empty{color:#78858a;font-size:10px}.inline-empty{padding:26px;text-align:center;border:1px dashed #d1dadd}.empty{min-height:380px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:800px){.facts{grid-template-columns:1fr 1fr}.mapping-band{grid-template-columns:1fr}.mapping-band>div{padding:5px 0}.grid{grid-template-columns:1fr;gap:0}.panel:first-child{padding-right:0;border-right:0;border-bottom:1px solid #dce2e5}.heading{align-items:flex-start;flex-direction:column}.snapshot-list article{grid-template-columns:1fr}.snapshot-list button{width:100%}.counts{grid-template-columns:1fr 1fr}.thead{display:none}.trow{grid-template-columns:1fr}.batch{grid-template-columns:1fr}.state{max-width:100%}}
</style>
